const value = $json.body.entry[0].changes[0].value;
const msg = value.messages[0];
const contact = (value.contacts && value.contacts[0]) || {};

let text = '';
let buttonPayload = null;

if (msg.type === 'text') {
  text = msg.text.body;
} else if (msg.type === 'interactive' && msg.interactive.type === 'button_reply') {
  text = msg.interactive.button_reply.title;
  buttonPayload = msg.interactive.button_reply.id;
} else if (msg.type === 'interactive' && msg.interactive.type === 'list_reply') {
  text = msg.interactive.list_reply.title;
  buttonPayload = msg.interactive.list_reply.id;
} else if (msg.type === 'button') {
  text = msg.button.text;
  buttonPayload = msg.button.payload;
} else {
  text = '[unsupported message type: ' + msg.type + ']';
}

return [{
  json: {
    from: msg.from,
    wa_message_id: msg.id,
    contact_name: contact.profile ? contact.profile.name : '',
    text: text,
    button_payload: buttonPayload,
    message_type: msg.type,
    timestamp: msg.timestamp
  }
}];

const rating = parseInt((($('WA • Extract Patient Message').item.json.text) || '').trim(), 10);
const pending = $json[0];
return [{
  json: {
    feedback_id: pending.id,
    appointment_id: pending.appointment_id,
    patient_phone: $('WA • Extract Patient Message').item.json.from,
    rating: rating
  }
}];

const items = $input.all();
const now = Date.now();
const out = [];
for (const item of items) {
  const j = item.json;
  const slot = new Date(j.slot_time).getTime();
  const hours = (slot - now) / 3600000;
  let type = null;
  if (hours <= 25 && hours >= 23 && !j.reminder_24h_sent) type = '24h';
  else if (hours <= 3 && hours >= 1 && !j.reminder_2h_sent) type = '2h';
  if (type) out.push({ json: { ...j, reminder_type: type } });
}
return out;

const b = $json.body || {};
return [{
  json: {
    call_id: b.call_id || '',
    appointment_id: b.appointment_id || null,
    patient_phone: b.patient_phone || '',
    status: b.status || 'unknown',
    outcome: b.outcome || 'no_answer',
    transcript_summary: b.transcript_summary || '',
    requested_new_time: b.requested_new_time || null
  }
}];

function randToken(len) {
  const chars = 'abcdef0123456789';
  let s = '';
  for (let i = 0; i < len; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}
const token = randToken(48);
const expiresAt = new Date(Date.now() + Number($env.REPORT_LINK_EXPIRY_DAYS || 7) * 24 * 3600 * 1000).toISOString();
const body = $('Webhook • Report Ready').item.json.body;
const patient = ($input.first().json[0]) || {};
return [{
  json: {
    patient_id: patient.id || body.patient_id,
    patient_name: patient.name || 'Patient',
    patient_phone: patient.phone || body.patient_phone,
    report_type: body.report_type,
    report_url: body.report_url,
    doctor_notes: body.doctor_notes || '',
    is_critical: body.is_critical === true,
    secure_token: token,
    expires_at: expiresAt,
    secure_link: ((($env.REPORT_PORTAL_BASE_URL || 'https://YOUR-REPORT-PORTAL-DOMAIN').replace(/\/$/, '')) + '/reports/view?token=' + token)
  }
}];

const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};
return [{
  json: {
    subject: '🔴 n8n Workflow Failed: ' + (wf.name || 'Unknown'),
    body: 'Workflow: ' + (wf.name || 'Unknown') + '\nFailed node: ' + (exec.lastNodeExecuted || 'Unknown') + '\nError: ' + (err.message || 'No message') + '\nExecution URL: ' + (exec.url || '') + '\nTime: ' + new Date().toISOString()
  }
}];
